// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import "../erc20/PendleERC20.sol";
import "./MarketMathCore.sol";

/// Live ETH Pendle Market (wstETH 30DEC2027) 0x34280882267ffa6383b363e278b027be083bbe3b.
/// Holds SY/PT reserves. Hybrid LP token + pool. Fixture only — not a finding.
contract PendleMarket is PendleERC20 {
    using MarketMathCore for uint256;
    uint256 public expiry;
    uint256 public totalPt;
    uint256 public totalSy;

    function mint(address receiver, uint256 netSyUsed, uint256 netPtUsed) external returns (uint256) {
        receiver; netSyUsed; netPtUsed;
        return MarketMathCore.addLiquidity(totalPt, totalSy, netPtUsed);
    }
    function burn(address receiverSy, address receiverPt, uint256 lpToRemove) external returns (uint256, uint256) {
        receiverSy; receiverPt;
        return (MarketMathCore.removeLiquidity(lpToRemove), 0);
    }
    function swapExactPtForSy(address receiver, uint256 exactPtIn, uint256 minSyOut) external returns (uint256) {
        receiver; minSyOut;
        return MarketMathCore.swapExactPtForSy(exactPtIn);
    }
    function swapSyForExactPt(address receiver, uint256 exactPtOut, uint256 maxSyIn) external returns (uint256) {
        receiver; maxSyIn;
        return MarketMathCore.swapSyForExactPt(exactPtOut);
    }
    function skim() external {}
    function readState() external view returns (uint256) { return expiry; }
    function readTokens() external view returns (address, address, address) { return (address(0), address(0), address(0)); }
}
